tape( 'if provided k > N, the function fills remaining slots with NaN', function test( t ) {
	var out;
	var x;

	x = [ 1.0, 2.0 ];
	out = [ 0.0, 0.0, 0.0 ];

	maxk( x.length, 3, x, 1, out, 1 );

	t.strictEqual( out[ 0 ], 1.0, 'returns expected value' );
	t.strictEqual( out[ 1 ], 2.0, 'returns expected value' );
	t.strictEqual( isnan( out[ 2 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided k > N, the function fills remaining slots with NaN (accessors)', function test( t ) {
	var obuf;
	var xbuf;
	var out;
	var x;

	xbuf = [ 1.0, 2.0 ];
	x = toAccessorArray( xbuf );
	obuf = [ 0.0, 0.0, 0.0 ];
	out = toAccessorArray( obuf );

	maxk( x.length, 3, x, 1, out, 1 );

	t.strictEqual( obuf[ 0 ], 1.0, 'returns expected value' );
	t.strictEqual( obuf[ 1 ], 2.0, 'returns expected value' );
	t.strictEqual( isnan( obuf[ 2 ] ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided N <= 0, the function fills output with NaN', function test( t ) {
	var out;
	var i;

	out = [ 1.0, 2.0, 3.0 ];

	maxk( 0, 3, [], 1, out, 1 );

	for ( i = 0; i < out.length; i++ ) {
		t.strictEqual( isnan( out[ i ] ), true, 'returns expected value' );
	}
	t.end();
});

tape( 'if provided N <= 0, the function fills output with NaN (accessors)', function test( t ) {
	var obuf;
	var out;
	var i;

	obuf = [ 1.0, 2.0, 3.0 ];
	out = toAccessorArray( obuf );

	maxk( 0, 3, toAccessorArray( [] ), 1, out, 1 );

	for ( i = 0; i < obuf.length; i++ ) {
		t.strictEqual( isnan( obuf[ i ] ), true, 'returns expected value' );
	}
	t.end();
});

